import{_ as t,o as a,c as r,a5 as n}from"./chunks/framework.BF53ZjCA.js";const g=JSON.parse('{"title":"Optical Tests","description":"","frontmatter":{"title":"Optical Tests","identification":"optical-tests"},"headers":[],"relativePath":"identification/optical-tests.md","filePath":"identification/optical-tests.md","lastUpdated":1790876393000}'),i={name:"identification/optical-tests.md"};function o(s,e,c,l,d,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="optical-tests" tabindex="-1">Optical Tests <a class="header-anchor" href="#optical-tests" aria-label="Permalink to &quot;Optical Tests&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Birefringence (polariscope), pleochroism (dichroscope), and UV fluorescence (UV lamp) provide optical and material clues — useful for screening species and deciding what to test next.</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-optical-tests-en"><p class="gem-identification-boundary__eyebrow">IDENTIFICATION BOUNDARY</p><h2 id="identification-boundary-optical-tests-en">Boundary &amp; Safety</h2><p>Optical phenomena are clues in an evidence chain, not shortcuts from an observation to a name. Polariscope, dichroscope, UV, and spectroscopy require suitable orientation, lighting/instrument conditions, and safe operation; fluorescence and absorption bands cannot alone prove natural, synthetic, treatment, or origin. </p></aside><h2 id="identification-steps" tabindex="-1">Identification Steps <a class="header-anchor" href="#identification-steps" aria-label="Permalink to &quot;Identification Steps&quot;">​</a></h2><p><strong>Shared teaching protocol</strong></p><p>Read every optical test in the same order: purpose → suitability → operation and record → interpretation → exception handling → risk/lab referral. Optical reactions depend on direction, cut, light, transparency, and instrument; preserve that context.</p><table tabindex="0"><thead><tr><th>Test</th><th>Primary output</th><th>Typical limits</th></tr></thead><tbody><tr><td>Polariscope</td><td>Optical character, extinction, and abnormal reaction</td><td>Direction, aggregates, polycrystalline structure, transparency</td></tr><tr><td>Dichroscope</td><td>Colour change, direction, and strength</td><td>Light source, cut, and viewing direction</td></tr><tr><td>UV fluorescence</td><td>LW/SW, colour, and intensity</td><td>Lamp, distance, background, and sample overlap</td></tr><tr><td>Spectroscopy</td><td>Absorption pattern, instrument, and reading quality</td><td>Calibration, optical path, direction, and interpretation</td></tr></tbody></table><h3 id="_1-polariscope-establish-optical-behavior-before-recording-it" tabindex="-1">1. Polariscope: establish optical behavior before recording it <a class="header-anchor" href="#_1-polariscope-establish-optical-behavior-before-recording-it" aria-label="Permalink to &quot;1. Polariscope: establish optical behavior before recording it&quot;">​</a></h3><p><strong>Purpose:</strong> Observe polarized-light reactions as clues for grouping candidates.</p><p><strong>Suitability:</strong> Place the specimen according to instrument instructions and confirm that shape, transparency, and internal structure suit observation. Mark aggregates, polycrystalline structures, and possible strain because they can create complex reactions.</p><p><strong>Operation and record:</strong> Record viewing direction, light/dark changes while rotating, whole or partial extinction, abnormal reactions, and instrument settings. Do not reduce the record to “birefringent”.</p><p><strong>Interpretation:</strong> Interpret birefringence, extinction, and abnormal reactions with cut, direction, transparency, and other properties. A higher value does not automatically make identification easier and cannot name a specimen alone.</p><p><strong>Exception handling:</strong> If the reaction is unstable, the internal structure is complex, or instrument and sample effects cannot be separated, record the uncertainty and use another evidence source.</p><p><strong>Risk/referral:</strong> Do not press or alter a specimen to obtain a reaction. Preserve conflicting results and refer formal-identification cases.</p><h3 id="_2-dichroscope-record-direction-and-colour-changes" tabindex="-1">2. Dichroscope: record direction and colour changes <a class="header-anchor" href="#_2-dichroscope-record-direction-and-colour-changes" aria-label="Permalink to &quot;2. Dichroscope: record direction and colour changes&quot;">​</a></h3><p><strong>Purpose:</strong> Observe pleochroism and directionality as supporting screening clues.</p><p><strong>Suitability:</strong> Use a stable light source and more than one viewing direction. Note whether the specimen is faceted, cabochon, transparent, or translucent because cut and light paths affect observations.</p><p><strong>Operation and record:</strong> Record colours, strength, direction, and light source separately from the candidate name.</p><p><strong>Interpretation:</strong> Pleochroism depends on crystal direction, cut, and light. No obvious change is an observation under current conditions, not a direct exclusion.</p><p><strong>Exception handling:</strong> If the change is weak, the field is unstable, or the light source differs, mark observation quality as limited rather than replacing it with a subjective colour label.</p><p><strong>Risk/referral:</strong> Avoid unnecessary manipulation of mounted or fragile specimens. Escalate formal disclosure to a qualified laboratory.</p><h3 id="_3-uv-fluorescence-record-band-and-conditions" tabindex="-1">3. UV fluorescence: record band and conditions <a class="header-anchor" href="#_3-uv-fluorescence-record-band-and-conditions" aria-label="Permalink to &quot;3. UV fluorescence: record band and conditions&quot;">​</a></h3><p><strong>Purpose:</strong> Record reactions under different UV bands to guide the next screening step.</p><p><strong>Suitability:</strong> Distinguish LW/SW conditions and record lamp, viewing distance, background, and sample state; confirm that the device meets its safety requirements.</p><p><strong>Operation and record:</strong> Record reaction colour, intensity, uniformity, and conditions. Distinguish “not observed” from “not stably observable with this setup”.</p><p><strong>Interpretation:</strong> Fluorescence can guide the next test, but natural, synthetic, and treated samples can overlap; it cannot alone establish identity, treatment, or origin.</p><p><strong>Exception handling:</strong> If ambient light, sample position, lamp condition, or repeatability is poor, mark the result quality and do not fill the gap from memory.</p><p><strong>Risk/referral:</strong> Follow UV eye and skin protection requirements and never stare at the source. Refer high-value, abnormal, or formal-disclosure cases.</p><h3 id="_4-spectroscopy-treat-absorption-bands-as-pattern-evidence" tabindex="-1">4. Spectroscopy: treat absorption bands as pattern evidence <a class="header-anchor" href="#_4-spectroscopy-treat-absorption-bands-as-pattern-evidence" aria-label="Permalink to &quot;4. Spectroscopy: treat absorption bands as pattern evidence&quot;">​</a></h3><p><strong>Purpose:</strong> Record absorption patterns as supporting evidence about structure, colour causes, and growth/treatment clues.</p><p><strong>Suitability:</strong> Record light source, instrument, calibration/check state, orientation, and optical path; thickness, transparency, and surface state affect reading quality.</p><p><strong>Operation and record:</strong> Record visible bands, overall pattern, reading quality, and repeats. If no stable spectrum is obtained, record that result instead of reconstructing it from memory.</p><p><strong>Interpretation:</strong> Cross-check patterns with RI, SG, inclusions, treatment clues, and sample limits. A spectrum is not an independent origin fingerprint, and one band cannot establish natural or synthetic identity.</p><p><strong>Exception handling:</strong> Preserve baseline drift, noise, unstable optical paths, and direction conflicts as unresolved evidence rather than selecting the expected plot.</p><p><strong>Risk/referral:</strong> Manage calibration, light source, and software output according to equipment requirements. Origin, natural/synthetic, and treatment opinions require a qualified laboratory.</p><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Interpret birefringence and polariscope reactions with anisotropy, direction, cut, and transparency; do not equate higher values with easier identification.</li><li>Pleochroism requires a stated light source, viewing direction, and colour-change strength; dichroscope results are candidate clues.</li><li>UV screening can guide the next test, but natural, synthetic, and treated samples can show overlapping reactions.</li><li>Spectral absorption is calibrated, recorded, cross-checked pattern evidence, not an independent fingerprint of origin.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Value</th><th>Note</th></tr></thead><tbody><tr><td>zircon</td><td>DR 0.059</td><td>Optical example; combine with direction and other evidence</td></tr><tr><td>iolite</td><td>strong pleochroism</td><td>Record the light source and viewing direction</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://www.gia.edu/gems-gemology/winter-2024-gemstone-analysis" target="_blank" rel="noreferrer">GIA: Analysis of Gemstones at GIA Laboratories</a><span>Standard gemological testing, laboratory workflow, and laboratory-grown diamond analysis examples</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2019-analytical-methods-geographic-origin-determination-gemstones" target="_blank" rel="noreferrer">GIA: Analytical Methods Used in Geographic Origin Determination</a><span>RI/SG as an identification starting point and further analysis for origin opinions</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2024-infrared-spectroscopy" target="_blank" rel="noreferrer">GIA: Infrared Spectroscopy and Its Use in Gemology</a><span>Spectroscopy and its relationship to atomic structure and natural/synthetic/treatment clues</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/ruby" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Ruby</a><span>Typical ruby RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/sapphire" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Sapphire</a><span>Typical sapphire RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/emerald" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Emerald</a><span>Typical emerald RI, birefringence, specific gravity, hardness, and treatment/synthetic/imitation context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/spinel" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Spinel</a><span>Typical spinel RI, isotropy, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/diamond" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Diamond</a><span>Typical diamond RI, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/zircon" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Zircon</a><span>Typical zircon RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/articles/iolite-description" target="_blank" rel="noreferrer">GIA: Iolite Description</a><span>Iolite pleochroism and viewing-direction context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/tanzanite-description" target="_blank" rel="noreferrer">GIA: Tanzanite Description</a><span>Tanzanite pleochroism, orientation, lighting, and heat-treatment context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/peridot" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Peridot</a><span>Typical peridot RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://my.gia.edu/FAQ/gia-faq-two-green-garnet" target="_blank" rel="noreferrer">GIA FAQ: Tsavorite and Demantoid</a><span>Green garnet colour overlap and mineral distinction context</span><small>Open source ↗</small></li></ul></aside><p><em>See the <a href="./intro.html">identification overview</a>.</em></p>',42)])])}const u=t(i,[["render",o]]);export{g as __pageData,u as default};
